-- Add BOTH new subjects (PP228 Water Governance + PP232 Microeconomics II) on top, in one run.
-- Idempotent upsert: removes any existing pp228/pp232 and re-inserts them at the top.
update public.catalog c
set data = jsonb_set(
  c.data,
  '{subjects}',
  (
    select coalesce(jsonb_agg(x.s order by x.ord), '[]'::jsonb)
    from (
      select s, ord::numeric + 2 as ord
        from jsonb_array_elements(c.data->'subjects') with ordinality as t(s, ord)
       where s->>'id' not in ('pp228','pp232')
      union all select $pp${"id":"pp228","lus":[{"id":"pp228_lu01","url":"https://opentakshashila.net/posts/pgp10-lu-01-urban-water-systems-in-the-overall-context-of-water-resources-in-india-103328220","title":"LU-01: Urban Water Systems in the Overall Context of Water Resources in India","outcomes":["Gain a comprehensive understanding of the complex challenges and frameworks surrounding water governance in India","Examine key issues like water scarcity, allocation rights and pollution management, and the roles of various stakeholders","Through analysis, discussion and case studies, develop strategies for sustainable and equitable water management in India"],"mandatory":[{"id":"pp228_lu01_m01","url":"https://drive.google.com/file/d/1LAN_b5rggBy2_PQXvkglYyC93YR1iGbK/view?usp=drive_link","desc":"Series of articles by Mihir Shah","name":"Series of Articles"},{"id":"pp228_lu01_m02","url":"https://drive.google.com/file/d/1JbWy6LXikecHMWbR-XrU8PHu9Omyy757/view?usp=sharing","desc":"Tirthankar Roy","name":"Water, Climate, and Economy in India from 1880 to the Present"},{"id":"pp228_lu01_m03","url":"https://drive.google.com/file/d/1YOV7_fWydvoe0RINEVVorTWSbNiOjOKj/view?usp=sharing","desc":"Akosua Sarpong Boakye-Ansah, Klaas Schwartz and Margreet Zwarteveen","name":"Unravelling pro-poor water services: what does it mean and why is it so popular?"},{"id":"pp228_lu01_m04","url":"https://drive.google.com/file/d/1LKOVaFzDd_crt7IVdLRa15bs2j2DWGiz/view?usp=sharing","desc":"ICRIER report","name":"Saving Punjab and Haryana from Ecological Disaster"}],"selfStudy":false,"recommended":[]}],"code":"Water Resources · Mr. Vishwanath","icon":"💧","name":"PP228: Water Governance","color":"#265d82"}$pp$::jsonb, 0::numeric
      union all select $pp${"id":"pp232","lus":[{"id":"pp232_lu01","url":"https://opentakshashila.net/posts/pgp10-introduction-to-market-failures-103328251","title":"LU-01: Introduction to Market Failures","outcomes":[],"mandatory":[{"id":"pp232_lu01_m01","url":"https://drive.google.com/file/d/1q0QRp2zlX20iOaUSJtbyOtDb74Kif0vO/view?usp=drive_link","desc":"Essay — an overview of the different types of market failures","name":"Is Market Failure a Sufficient Condition for Government Intervention?"},{"id":"pp232_lu01_m02","url":"https://drive.google.com/file/d/1hKEY7gzPucrjWF4L_H07e8BKCW_2MXTB/view?usp=sharing","desc":"Opinion piece by Anupam Manur — a market-failure lens on the Indira Canteens","name":"The Irony of Indira"}],"selfStudy":false,"recommended":[]},{"id":"pp232_lu02","url":"https://opentakshashila.net/posts/pgp10-introduction-to-market-structure","title":"LU-02: Introduction to Market Structure","outcomes":["Understand the different ways in which markets are structured","Learn the typical characteristics of a perfectly competitive market","Understand how a monopoly, oligopoly and monopolistic competition work","Understand how a government regulates uncompetitive markets"],"mandatory":[{"id":"pp232_lu02_m01","url":"https://drive.google.com/file/d/19qlwTdaGAWLDHTdmdhmKAvKdfsQmyDuM/view?usp=sharing","desc":"Book chapter on the characteristics of an oligopoly and measures of market concentration","name":"Oligopoly: Competition Among the Few"},{"id":"pp232_lu02_m02","url":"https://drive.google.com/file/d/1-iSYGbv1zGzpoHn22cMneom9Jl71dXT8/view?usp=sharing","desc":"Essay by George J. Stigler","name":"Monopoly"}],"selfStudy":false,"recommended":[{"id":"pp232_lu02_r01","url":"","desc":"Pindyck & Rubinfeld, Chapters 10–12 (textbook — covers these topics in more detail than needed at this stage)","name":"Microeconomics"},{"id":"pp232_lu02_r02","url":"https://drive.google.com/file/d/1qdQ6dY6cBma116DHLjIJsxVIxCdll0dr/view?usp=sharing","desc":"Grady Klein and Yoram Bauman (Chapter 10)","name":"The Cartoon Introduction to Economics, Volume One: Microeconomics"}]},{"id":"pp232_lu05","url":"https://opentakshashila.net/posts/pgp10-lu-05-market-failures-externalities","title":"LU-05: Market Failures: Externalities","outcomes":["Recognise that every economic action can have an effect on economic agents who are not directly involved in the action","Understand positive and negative externalities, and government intervention to deal with the two"],"mandatory":[{"id":"pp232_lu05_m01","url":"https://www.youtube.com/watch?v=CpVf11f09Pk","desc":"MRU video — private cost, external cost and social cost","name":"An Introduction to Externalities"},{"id":"pp232_lu05_m02","url":"https://drive.google.com/file/d/1-njN3c1nS7IroDLpsz5exwX9S0y5BsYv/view?usp=drive_link","desc":"Essay by Bryan Caplan","name":"Externalities"},{"id":"pp232_lu05_m03","url":"https://www.youtube.com/watch?v=1G-_HL9ZE24","desc":"MRU video — vaccines produce positive externalities","name":"External Benefits"},{"id":"pp232_lu05_m04","url":"https://www.youtube.com/watch?v=00HPak2RLlQ","desc":"Video — bees and pollination demonstrate the Coase Theorem","name":"The Coase Theorem"},{"id":"pp232_lu05_m05","url":"https://youtu.be/9tUb3MDrgEc","desc":"Video — the market finds the lowest-cost way of reducing pollution","name":"Trading Pollution"},{"id":"pp232_lu05_m06","url":"https://youtu.be/gRolVmFOk1U","desc":"Video — when command-and-control makes sense (smallpox eradication)","name":"Command and Control Solutions"}],"selfStudy":false,"recommended":[{"id":"pp232_lu05_r01","url":"https://drive.google.com/file/d/12Nvu_YdatQ7d2CSzHJdlhZDfcgUr81Iw/view?usp=drive_link","desc":"Paper by Donald J. Boudreaux & Roger Meiners","name":"Externality: Origins and Classifications"},{"id":"pp232_lu05_r02","url":"https://drive.google.com/file/d/1srcRy-6iT-y35jHcar4j2x2Jen8EbDNx/view?usp=drive_link","desc":"Blog by Alex Tabarrok","name":"Air Pollution Kills"},{"id":"pp232_lu05_r03","url":"https://drive.google.com/file/d/1gFqDhiV9clMVtewfGXyuf8jVO4c5pLV7/view?usp=sharing","desc":"Analysis of the externalities associated with schooling","name":"Is Public Schooling a Public Good?"},{"id":"pp232_lu05_r04","url":"https://freakonomics.com/podcast/how-stupid-is-our-obsession-with-lawns/","desc":"Freakonomics Radio podcast","name":"How Stupid Is Our Obsession With Lawns?"},{"id":"pp232_lu05_r05","url":"https://drive.google.com/file/d/1YWhxQDkAAZ_7by_F6JJijnn0F-rHTWAf/view?usp=sharing","desc":"Measures the welfare loss from the largest nuclear accident","name":"The long-run consequences of Chernobyl"},{"id":"pp232_lu05_r06","url":"https://www.nytimes.com/2000/07/13/business/economic-scene-when-it-comes-enforcing-taste-it-s-best-tread-lightly-if-all.html","desc":"NYT article on the spillover effect of poor aesthetics","name":"Economic Scene: When it comes to enforcing taste, it's best to tread lightly — if at all"},{"id":"pp232_lu05_r07","url":"https://drive.google.com/file/d/1vy1L1k7syB8bqPrEsntPuPlwNCnj0ibR/view?usp=drive_link","desc":"Essay by Michael Munger","name":"Orange Blossom Special: Externalities and the Coase Theorem"}]},{"id":"pp232_lu06","url":"https://opentakshashila.net/posts/pgp10-lu-06-market-failures-public-goods","title":"LU-06: Market Failures: Public Goods","outcomes":["Understand the key concepts of rivalry and excludability","Understand what public goods are and why markets fail to provide them"],"mandatory":[{"id":"pp232_lu06_m01","url":"https://www.econlib.org/library/Enc/PublicGoods.html","desc":"Essay by Tyler Cowen (Econlib)","name":"Introduction to Public Goods"},{"id":"pp232_lu06_m02","url":"https://www.youtube.com/watch?v=lLzcW5NG5eA","desc":"MRU video — asteroid defence as a public good","name":"Public Goods and Asteroid Defence"},{"id":"pp232_lu06_m03","url":"https://www.youtube.com/watch?v=hA2z-X31IvI","desc":"MRU video — classifying goods by rivalry and excludability","name":"A Deeper Look at Public Goods"}],"selfStudy":false,"recommended":[{"id":"pp232_lu06_r01","url":"https://www.youtube.com/watch?v=Qr5Q3VvpI7w","desc":"Elinor Ostrom on governing the commons","name":"Ending the Tragedy of the Commons"},{"id":"pp232_lu06_r02","url":"https://drive.google.com/file/d/1CcT2yRG-loyk5gIh0Ruj7Kuu3WGZHKN5/view?usp=sharing","desc":"Anthony de Jasay","name":"The Public Goods Dilemma"},{"id":"pp232_lu06_r03","url":"https://drive.google.com/file/d/1UCBLvBVi2H2yRl5JI5HWJKZ3iD35wBmh/view?usp=drive_link","desc":"Essay by Bryan Caplan","name":"The Public Goods Model vs. Social Desirability Bias: A Case of Observational Equivalence"}]},{"id":"pp232_lu07","url":"https://opentakshashila.net/posts/pgp10-lu-07-market-failures-information-asymmetry","title":"LU-07: Market Failures: Information Asymmetry","outcomes":["Understand the conditions under which markets fail to produce the most efficient outcomes","Appreciate the crucial role information plays in efficient outcomes; a lack of it leads to inefficiencies and adverse selection","Understand the role of risk in economic behaviour and how it leads to moral hazard and principal-agent problems"],"mandatory":[{"id":"pp232_lu07_m01","url":"https://drive.google.com/file/d/18MV_G9geRUN2GI984lTPa4azP9Z-d4Ix/view?usp=sharing","desc":"Essay by Morgan Rose","name":"Implications of Costly Information"},{"id":"pp232_lu07_m02","url":"https://www.youtube.com/watch?v=sXPXpJ5vMnU","desc":"MRU video — the market for used cars (lemons)","name":"Asymmetric Information and Used Cars"},{"id":"pp232_lu07_m03","url":"https://www.youtube.com/watch?v=pUkRo9COd38","desc":"MRU video — asymmetric information in health insurance","name":"Asymmetric Information and Health Insurance"},{"id":"pp232_lu07_m04","url":"https://www.youtube.com/watch?v=5v7TWKlYoN0","desc":"MRU video — the concept of moral hazard","name":"Moral Hazard"},{"id":"pp232_lu07_m05","url":"https://drive.google.com/file/d/1GL2PPMQMSadKJHl4Y0uKC-y1mEhf2wNF/view?usp=sharing","desc":"Forbes article — opioid abuse rising as it became less risky/costly","name":"Moral Hazard May Be Negating Efforts To Decrease Opioid Overdoses"},{"id":"pp232_lu07_m06","url":"https://youtu.be/6faL76QZ2AA","desc":"MRU video — solutions to moral hazard","name":"Solutions to Moral Hazard"},{"id":"pp232_lu07_m07","url":"https://www.youtube.com/watch?v=kd2r3ARB2tk","desc":"MRU video — the principal-agent problem","name":"What Is the Principal-Agent Problem?"},{"id":"pp232_lu07_m08","url":"https://www.youtube.com/watch?v=F8ZHZRMSxKg","desc":"Video — signals reveal information","name":"Signalling"}],"selfStudy":false,"recommended":[{"id":"pp232_lu07_r01","url":"https://drive.google.com/file/d/1J9QeT4QPOv9geiPWa4KCyuqnqH_7dJwy/view?usp=sharing","desc":"George A. Akerlof's widely cited paper","name":"The Market for \"Lemons\": Quality Uncertainty and the Market Mechanism"},{"id":"pp232_lu07_r02","url":"https://drive.google.com/file/d/1iDaxDshUrdFYx_3vM7KR5iepW2Mnq6nc/view?usp=sharing","desc":"Essay by Bryan Caplan","name":"A Closer Look at Adverse Selection and Mandatory Insurance"},{"id":"pp232_lu07_r03","url":"https://drive.google.com/file/d/1P1hvnQEu0EZ755pPket0KLSNKljo_C0x/view?usp=sharing","desc":"Essay by Kevin Corcoran","name":"Moral Hazard and Health Insurance"},{"id":"pp232_lu07_r04","url":"https://drive.google.com/file/d/1NFGIeL8ExmRY2qIJN7uNbcE3jFo49s9g/view?usp=sharing","desc":"News article on misaligned incentives","name":"Firefighters in Sicily accused of starting blazes for cash"},{"id":"pp232_lu07_r05","url":"https://drive.google.com/file/d/1rCB1gmuChSHQ2-MBLmbWWC39SZ8sItTU/view?usp=sharing","desc":"An analysis of corruption","name":"Corruption is BOTH a \"Principal-Agent Problem\" AND a \"Collective Action Problem\""},{"id":"pp232_lu07_r06","url":"https://docs.google.com/document/d/1LY8YSoPGl3_00ow5HoEdo-vRt6dIxTTJ/edit?usp=sharing","desc":"Planet Money podcast on information asymmetry in dating","name":"The Liars of Romance"},{"id":"pp232_lu07_r07","url":"https://www.youtube.com/watch?v=MvWnyUT7vPk","desc":"MRU video — is education signalling or skill building?","name":"Econ Duel: Is Education Signalling or Skill Building?"}]},{"id":"pp232_lu08","url":"https://opentakshashila.net/posts/pgp10-lu-08-government-intervention-in-the-market-taxes-and-subsidies","title":"LU-08: Government Intervention in the Market: Taxes and Subsidies","outcomes":["Learn about the incidence of taxes","Understand the unintended consequences of government intervention"],"mandatory":[{"id":"pp232_lu08_m01","url":"https://youtu.be/1H5uU_6Ax_4","desc":"MRU video — who bears the burden of a tax","name":"Who pays the tax?"},{"id":"pp232_lu08_m02","url":"https://youtu.be/dbuU8S1x0Ro","desc":"MRU video — taxes, consumer surplus and producer surplus","name":"Tax revenue and deadweight loss"},{"id":"pp232_lu08_m03","url":"https://youtu.be/LTFxRlACebk","desc":"MRU video — how a subsidy plays out and who benefits","name":"Subsidies"},{"id":"pp232_lu08_m04","url":"https://drive.google.com/file/d/11eILJO0P3Rl4yTtuarISs7SSgjP1yEsM/view?usp=sharing","desc":"News article on the effectiveness of soda taxes","name":"Berkeley has America's first soda tax, but stores are barely raising drink prices"}],"selfStudy":false,"recommended":[{"id":"pp232_lu08_r01","url":"https://drive.google.com/file/d/1jkcFtRQuXXgVhImCmsCFfD821SgP6a_x/view?usp=sharing","desc":"A slightly advanced, in-depth exploration of subsidies","name":"Types of Subsidies"},{"id":"pp232_lu08_r02","url":"https://youtu.be/iOmDo5jLFw8","desc":"Extra resource — video","name":"Indifference Curves"},{"id":"pp232_lu08_r03","url":"https://youtu.be/sNRZE0kwNGI","desc":"Extra resource — video","name":"Budget Constraints"},{"id":"pp232_lu08_r04","url":"https://youtu.be/MXIgp-P-FeY","desc":"Extra resource — video","name":"Consumer Optimization"}]}],"code":"Microeconomics","icon":"📊","name":"PP232: Microeconomics II","color":"#7a4c1f"}$pp$::jsonb, 1::numeric
